    clearPdfjsCommitRaf,
    clearPdfjsInteractionTimer,
    clearPdfjsOverlayTransformSyncRaf,
    finalizePdfjsInteractionIdle,
    runPdfjsCommitQueue,
    sortPdfjsPagesByDistance,
    syncPdfjsLightweightPages
